// ============================================================================
//  MULTI-CLINICA
//  Este nodo no da por hecho que solo existe una clinica. Cruza cada cita con
//  su clinica para saber tres cosas:
//    - desde que numero de WhatsApp hay que enviar (telefono_whatsapp_id)
//    - en que zona horaria vive esa clinica        (zona_horaria)
//    - como se llama, para que el mensaje lo diga  (nombre)
//
//  Dar de alta una clinica nueva = insertar una fila en la tabla clinicas.
//  Este codigo NO se toca.
// ============================================================================

// AVISO: las clinicas hay que leerlas POR EL NOMBRE del nodo.
// $input aqui devuelve las CITAS (el nodo inmediatamente anterior), no las
// clinicas. Es el mismo fallo que rompio el workflow 04 en agosto.
const clinicas = new Map(
  $('Cargar clinicas').all()
    .map(item => item.json || {})
    .filter(c => c.id)
    .map(c => [c.id, c])
);

// BAJAS (15-sep-2026): pacientes que han escrito BAJA al bot. No se les manda
// nada. Antes, "stop" solo cerraba un lead y el recordatorio llegaba igual.
const soloDigitos = v => (v || '').toString().replace(/\D/g, '');
const bajas = new Set(
  $('Cargar bajas').all()
    .map(item => item.json || {})
    .filter(p => p.id && p.opt_out === true)
    .map(p => p.clinica_id + '|' + soloDigitos(p.telefono).slice(-9))
);
const pidioBaja = row => bajas.has(row.clinica_id + '|' + soloDigitos(row.telefono).slice(-9));

// PLANTILLA DE META (15-sep-2026). Fuera de la ventana de 24 h Meta solo deja
// enviar plantillas aprobadas, y un recordatorio sale casi siempre fuera de
// ventana: con texto libre fallaba con el error 131047.
// El nombre y el idioma tienen que coincidir EXACTAMENTE con la plantilla
// aprobada en el Administrador de WhatsApp:
//   idioma "Spanish"       -> 'es'
//   idioma "Spanish (SPA)" -> 'es_ES'
// Texto de la plantilla: Negocio/Meta - todo lo que bloquea.md, apartado 3.
//   {{1}} nombre   {{2}} tratamiento   {{3}} hora   {{4}} clinica
const PLANTILLA_RECORDATORIO = 'recordatorio_cita_24h';
const IDIOMA_PLANTILLA = 'es';

// Meta rechaza variables vacias, con saltos de linea o con muchos espacios.
const paramPlantilla = (valor, porDefecto) => {
  const limpio = (valor || '').toString().replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 60);
  return limpio || porDefecto;
};

const ZONA_POR_DEFECTO = 'Europe/Madrid';

// "Manana" no es la misma fecha para todas las clinicas: depende de su zona.
// Una clinica espanola y una portuguesa pueden estar en dias distintos a las
// 00:30. Por eso se calcula una vez por zona, no una vez para todos.
const calcularManana = zona => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zona,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date(Date.now() + 24 * 60 * 60 * 1000));
  const get = tipo => parts.find(p => p.type === tipo).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const cacheManana = new Map();
const manana = zona => {
  if (!cacheManana.has(zona)) cacheManana.set(zona, calcularManana(zona));
  return cacheManana.get(zona);
};

// Supabase devuelve booleanos reales. Aceptamos tambien los textos 'no'/'false'
// que venian de Google Sheets, por si queda alguna fila migrada a mano.
const pendienteDeEnviar = v => v === false
  || v === null
  || v === undefined
  || ['no', 'false', ''].includes(v.toString().toLowerCase().trim());

// La columna fecha es de tipo date: Supabase la devuelve como 'YYYY-MM-DD'.
const normFecha = f => {
  if (!f) return '';
  const v = f.toString().trim();
  const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return iso ? iso[1] + '-' + iso[2] + '-' + iso[3] : v;
};

// La busqueda de Supabase trae de mas a proposito (desde ayer en adelante) y
// quien decide que cita toca es este codigo, que si conoce la zona de cada
// clinica. Filtrar por la fecha exacta de manana en la consulta fallaria con
// clinicas en husos distintos.
//
// AVISO: el nodo de Supabase de n8n NO admite dos condiciones sobre la misma
// columna: la segunda pisa a la primera. Por eso hay un solo filtro de fecha
// y el limite superior lo pone este codigo, no la consulta.
return $input.all()
  .map(item => item.json || {})
  .map(row => ({ row, clinica: clinicas.get(row.clinica_id) }))
  .filter(({ row, clinica }) => {
    // Sin clinica, desactivada o sin numero de WhatsApp no se envia nada.
    if (!clinica || clinica.activo === false) return false;
    if (!clinica.telefono_whatsapp_id) return false;

    const zona     = clinica.zona_horaria || ZONA_POR_DEFECTO;
    const estado   = (row.estado || '').toString().toLowerCase().trim();
    const telefono = (row.telefono || '').toString().trim();

    return normFecha(row.fecha) === manana(zona)
      && estado === 'confirmada'
      && pendienteDeEnviar(row.recordatorio_24h)
      && telefono !== ''
      && !!row.event_id
      && !pidioBaja(row);
  })
  .map(({ row, clinica }) => ({
    json: {
      ...row,
      eventId:        row.event_id,
      telefono:       row.telefono.toString(),
      // Lo lee el nodo "Enviar recordatorio". Cada clinica envia desde SU numero.
      phoneNumberId:  clinica.telefono_whatsapp_id,
      clinicaNombre:  clinica.nombre,
      plantilla:         PLANTILLA_RECORDATORIO + '|' + IDIOMA_PLANTILLA,
      param_nombre:      paramPlantilla((row.nombre || '').trim().split(/\s+/)[0], 'paciente'),
      param_tratamiento: paramPlantilla(row.tratamiento, 'tu tratamiento'),
      param_hora:        paramPlantilla(row.hora, 'la hora reservada'),
      param_clinica:     paramPlantilla(clinica.nombre, 'la clínica')
    }
  }));

// Envios que Meta ha RECHAZADO (plantilla no aprobada, numero invalido, token
// caducado...). Los que si salieron ya estan marcados como enviados; estos NO.
// Se junta todo en un solo error para que el workflow 04 te avise UNA vez, y
// despues "Avisar fallos" hace fallar la ejecucion a proposito.
const fallos = $input.all().map(item => {
  const e = item.json && item.json.error;
  const texto = typeof e === 'string'
    ? e
    : (e && (e.message || e.description)) || JSON.stringify(item.json || {});
  return texto.toString().replace(/\s+/g, ' ').slice(0, 200);
});

if (!fallos.length) return [];

return [{
  json: {
    mensaje: fallos.length + ' envio(s) rechazados por WhatsApp. No se han marcado como enviados. Primer error: ' + fallos[0]
  }
}];
